INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10931, '6 định dạng cần có trong Lời nhắc ChatGPT', 'su-dung-chat-gpt-ca-nhan', '		<div data-elementor-type="wp-post" data-elementor-id="10931" class="elementor elementor-10931" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-d1bdbc1 e-flex e-con-boxed e-con e-parent" data-id="d1bdbc1" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-b2c7600 elementor-widget elementor-widget-heading" data-id="b2c7600" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h1 class="elementor-heading-title elementor-size-default">6 định dạng cần có trong Lời nhắc ChatGPT</h1>				</div>
				</div>
				<div class="elementor-element elementor-element-e23b9b2 elementor-widget elementor-widget-text-editor" data-id="e23b9b2" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<div class="group w-full text-token-text-primary border-b border-black/10 dark:border-gray-900/50 bg-gray-50 dark:bg-[#444654]" data-testid="conversation-turn-7"><div class="p-4 justify-center text-base md:gap-6 md:py-6 m-auto"><div class="flex flex-1 gap-4 text-base mx-auto md:gap-6 md:max-w-2xl lg:max-w-[38rem] xl:max-w-3xl }"><div class="relative flex w-[calc(100%-50px)] flex-col gap-1 md:gap-3 lg:w-[calc(100%-115px)]"><div class="flex flex-grow flex-col gap-3 max-w-full"><div class="min-h-[20px] flex flex-col items-start gap-3 overflow-x-auto whitespace-pre-wrap break-words"><div class="markdown prose w-full break-words dark:prose-invert light"><p>Để cải thiện lời nhắc trong ChatGPT, hãy hiểu 6 thành phần nhắc nhở chính: task (nhiệm vụ), context (bối cảnh), exemplar (khuôn mẫu), persona (tính cách), format (định dạng), và tone (giọng điệu). Nhiệm vụ là cần thiết, bối cảnh và mẫu mực là quan trọng, và tính cách, hình thức và giọng điệu sẽ nâng cao kết quả. Việc cân bằng các thành phần này sẽ nâng cao hiệu quả kỹ năng nhắc nhở của bạn.</p></div></div></div></div></div></div></div>								</div>
				</div>
				<div class="elementor-element elementor-element-e157954 elementor-widget elementor-widget-jet-accordion" data-id="e157954" data-element_type="widget" data-widget_type="jet-accordion.default">
				<div class="elementor-widget-container">
							<div class="jet-accordion" data-settings="{&quot;collapsible&quot;:false,&quot;ajaxTemplate&quot;:false,&quot;switchScrolling&quot;:false,&quot;switchScrollingOffset&quot;:0,&quot;switchScrollingDelay&quot;:500}">
			<div class="jet-accordion__inner">
				<div class=" jet-accordion__item jet-toggle jet-toggle-move-up-effect ">
							<div id="jet-toggle-control-2361" class="jet-toggle__control elementor-menu-anchor" data-toggle="1" role="button" tabindex="0" aria-controls="jet-toggle-content-2361" aria-expanded="false" data-template-id="false">
								<div class="jet-toggle__label-icon jet-toggle-icon-position-left"><span class="jet-toggle__icon icon-normal jet-tabs-icon"><i class="fas fa-plus"></i></span><span class="jet-toggle__icon icon-active jet-tabs-icon"><i class="fas fa-minus"></i></span></div><div class="jet-toggle__label-text">6 định dạng là gì?</div>							</div>
							<div id="jet-toggle-content-2361" class="jet-toggle__content" data-toggle="1" role="region" data-template-id="false">
								<div class="jet-toggle__content-inner"><p><span>Trong hành trình làm người mới bắt đầu, bạn sẽ khám phá tiềm năng đáng kinh ngạc của ChatGPT. Bạn sẽ thấy đây là một công cụ linh hoạt có thể hỗ trợ bạn thực hiện nhiều nhiệm vụ khác nhau, từ soạn email ngắn gọn đến xây dựng chiến lược tiếp thị toàn diện. Trong quá trình thực hiện, bạn thậm chí có thể lưu một số lời nhắc để tham khảo trong tương lai. Tuy nhiên, bạn cũng sẽ gặp phải một thách thức chung – hiểu lý do tại sao một số lời nhắc tạo ra kết quả xuất sắc trong khi những lời nhắc khác tạo ra kết quả chung chung và không thể sử dụng được.</span></p><p><span>Để nâng cao trình độ chuyên môn tiếp theo, điều quan trọng là phải nắm bắt được sáu thành phần thiết yếu của một lời nhắc mạnh mẽ: nhiệm vụ, bối cảnh, gương mẫu, tính cách, hình thức và giọng điệu. Trong khi tất cả sáu thành phần đều có tầm quan trọng riêng, một số thành phần quan trọng hơn những thành phần khác. Một nhiệm vụ là hoàn toàn bắt buộc, bối cảnh và ví dụ là rất quan trọng. Tính cách, hình thức và giọng điệu, mặc dù không bắt buộc, nhưng lại là điều cần thiết để đạt được kết quả tốt nhất.</span></p><p><span>Khi tích lũy được kinh nghiệm, bạn sẽ học cách đạt được sự cân bằng giữa các thành phần này một cách hiệu quả. Khi tạo lời nhắc, điều cần thiết là phải xem xét nhiệm vụ, bối cảnh, mẫu mực, tính cách, hình thức và giọng điệu. Ví dụ: bạn có thể chuyển một lời nhắc yếu thành một lời nhắc mạnh mẽ bằng cách thêm một nhân vật cụ thể, cung cấp ngữ cảnh phù hợp và điều chỉnh giọng điệu cho phù hợp với kết quả mong muốn. Sự hiểu biết cơ bản về sáu thành phần này sẽ nâng cao đáng kể kỹ năng của bạn trong việc tạo ra những gợi ý hiệu quả.</span></p><p>In your journey as a beginner, you&#8217;ll discover the incredible potential of ChatGPT. You&#8217;ll find it to be a versatile tool that can assist you in a wide range of tasks, from composing concise emails to formulating comprehensive marketing strategies. Along the way, you might even save some prompts for future reference. However, you&#8217;ll also encounter a common challenge – understanding why some prompts generate excellent results while others produce generic and unusable outputs.</p><p>To advance to the next level of expertise, it&#8217;s crucial to grasp the six essential components of a strong prompt: task, context, exemplar, persona, format, and tone. While all six components have their significance, some are more critical than others. A task is absolutely mandatory, and context and exemplar are highly important. Persona, format, and tone, while not mandatory, are desirable for achieving the best outcomes.</p><p>As you gain experience, you&#8217;ll learn to strike a balance between these components effectively. When crafting a prompt, it&#8217;s essential to consider the task, context, exemplar, persona, format, and tone. For instance, you can transform a weak prompt into a powerful one by adding a specific persona, providing relevant context, and adjusting the tone to suit the desired outcome. This fundamental understanding of the six components will significantly enhance your skills in crafting effective prompts.</p></div>
							</div>
						</div>			</div>
		</div>
						</div>
				</div>
		<div class="elementor-element elementor-element-7fc3233 e-flex e-con-boxed e-con e-parent" data-id="7fc3233" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-e835c30 elementor-widget elementor-widget-text-editor" data-id="e835c30" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong><span style="color: #ffff00;">Task</span> &#8211; <span style="color: #ff0000;">Context</span> &#8211; <span style="color: #ff9900;">Exemplar</span> &#8211; <span style="color: #3366ff;">Persona</span> &#8211; <span style="color: #00ff00;">Format</span> &#8211; <span style="color: #ff99cc;">Tone</span></strong></p>								</div>
				</div>
				<div class="elementor-element elementor-element-2c0fd0d elementor-widget elementor-widget-text-editor" data-id="2c0fd0d" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Bạn là <strong><span style="color: #3366ff;">nhân viên hỗ trợ (nhân vật) am hiểu công nghệ và hướng đến khách hàng</span></strong>, <strong><span style="color: #ff0000;">giải quyết vấn đề của khách hàng với điện thoại thông minh bị trục trặc</span></strong> (bối cảnh). <strong><span style="color: #00ff00;">Đưa ra phản hồi (định dạng) ngắn gọn và đồng cảm</span></strong> để <strong><span style="color: #ff9900;">khắc phục sự cố, cung cấp hướng dẫn từng bước (mẫu mực)</span></strong> trong khi vẫn duy trì <strong><span style="color: #ff99cc;">giọng điệu (giọng điệu) kiên nhẫn và hữu ích</span></strong> để <strong><span style="color: #ffff00;">đảm bảo giải pháp (nhiệm vụ) thỏa đáng</span></strong>.</p><p>Hãy tưởng tượng bạn là <strong><span style="color: #3366ff;">một đầu bếp đam mê và có ý thức về môi trường</span></strong> (nhân cách) <strong><span style="color: #ff0000;">đang giới thiệu một thực đơn</span></strong> (bối cảnh) mới dựa trên thực vật tại nhà hàng của bạn. <strong><span style="color: #00ff00;">Viết mô tả (định dạng) hấp dẫn</span></strong> về các món ăn đặc trưng của bạn, <strong><span style="color: #ff9900;">làm nổi bật hương vị thơm ngon và nguyên liệu bền vững của chúng (mẫu mực)</span></strong> với <strong><span style="color: #ff99cc;">giọng điệu (giọng điệu) nhiệt tình và thân thiện với môi trường</span> <span style="color: #ffff00;">để lôi kéo thực khách thử những sáng tạo (nhiệm vụ) sáng tạo của bạn</span></strong>.</p><p>Bạn là <span style="color: #3366ff;"><strong>một người quản lý dự án siêng năng và có định hướng chi tiết</strong></span> (nhân cách) <strong><span style="color: #ff0000;">được giao nhiệm vụ tổ chức một khóa tu</span></strong> (bối cảnh) xây dựng nhóm cho công ty của bạn. Hãy <strong><span style="color: #00ff00;">soạn một email (định dạng) rõ ràng và thuyết phục</span> <span style="color: #ff9900;">nêu rõ các mục tiêu, hành trình và lợi ích mong đợi của khóa tu</span></strong> (mẫu) với <strong><span style="color: #ff99cc;">giọng điệu (giọng điệu) chuyên nghiệp và động viên</span></strong> nhằm <strong><span style="color: #ffff00;">khuyến khích sự tham gia và nhiệt tình (nhiệm vụ) của nhân viên</span></strong>.</p>								</div>
				</div>
					</div>
				</div>
					</div>
				</div>
				</div>
		', 'Để cải thiện lời nhắc trong ChatGPT, hãy hiểu 6 thành phần nhắc nhở chính: task (nhiệm vụ), context (bối cảnh), exemplar (khuôn mẫu), persona (tính cách), format (định dạng), và tone (giọng điệu). Nhiệm vụ là cần thiết, bối cảnh và mẫu mực là quan trọng, và tính cách, hình thức và giọng điệu [&hellip;]', NULL, 'post', '2023-09-05 19:09:20', '2023-09-13 10:05:51');
