INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (10837, 'Cơ bản về Gen AI', 'co-ban-ve-gen-ai', '		<div data-elementor-type="wp-post" data-elementor-id="10837" class="elementor elementor-10837" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-1f18aba e-flex e-con-boxed e-con e-parent" data-id="1f18aba" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-5fd0352 e-con-full e-flex e-con e-parent" data-id="5fd0352" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-c987902 elementor-widget elementor-widget-heading" data-id="c987902" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h1 class="elementor-heading-title elementor-size-default">Cơ bản về Gen AI</h1>				</div>
				</div>
				</div>
		<div class="elementor-element elementor-element-e3c9722 e-con-full e-flex e-con e-parent" data-id="e3c9722" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-bf57f12 elementor-widget elementor-widget-text-editor" data-id="bf57f12" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
